 use vstd::prelude::*;

 fn main() {}

 verus!{

 // File: defs.rs
 pub struct Execution<T> {
     pub nat_to_state: spec_fn(nat) -> T,
 }

 impl<T> Execution<T> {

     pub open spec fn suffix(self, pos: nat) -> Self {
         Execution {
             nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
         }
     }

 }


 #[verifier(reject_recursive_types(T))]
 pub struct TempPred<T> {
     pub pred: spec_fn(Execution<T>) -> bool,
 }

 impl<T> TempPred<T> {

     pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
         TempPred {
             pred: pred,
         }
     }

     pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
         (self.pred)(execution)
     }

     pub open spec fn and(self, other: Self) -> Self {
         TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) && other.satisfied_by(ex))
     }

     pub open spec fn implies(self, other: Self) -> Self {
         TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
     }

 }


 pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
     TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
 }

 pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
     forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
 }


 // File: rules.rs
 proof fn always_unfold<T>(ex: Execution<T>, p: TempPred<T>)
 		requires always(p).satisfied_by(ex),
 		ensures forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(i)),
 {
 		// Unfold `always(p)` which is defined as
 		//   TempPred::new(|ex| forall i: nat. p.satisfied_by(ex.suffix(i))).
 		assert forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(i)) by {
 		    // Directly use the requirement `always(p).satisfied_by(ex)`.
 		    // This requirement already *is* the desired forall once `always` is unfolded.
 		    // Reveal the definition of `always`.
 		    reveal(always(p).satisfied_by(ex));
 		}
 	}

 proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
     ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
 {
     // `valid` is a spec for all executions: valid(X) := forall ex. X.satisfied_by(ex)
     // So the ensures is: forall ex. always(p.and(q)).satisfied_by(ex) ==> (always(p).and(always(q))).satisfied_by(ex).

     // Prove the implication pointwise.
     assert forall |ex: Execution<T>|
         always(p.and(q)).satisfied_by(ex)
             ==> (always(p).and(always(q))).satisfied_by(ex) by {
         if always(p.and(q)).satisfied_by(ex) {
             // `and` for predicates is pointwise conjunction, so it suffices to show
             //   forall i. (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i)))
             // and then this matches the required `always(p).and(always(q))` unfolding.
             assert forall |i: nat| #[trigger] (p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i))) by {
                 always_unfold(ex, p.and(q));
             };

             // Now conclude `(always(p).and(always(q))).satisfied_by(ex)` by unfolding it.
             reveal(always(p).and(always(q)).satisfied_by(ex));
         }
     };
 }


 }

